ens = simulationEnsembleDatastore("simResults");
ens.SelectedVariables = ["Vibration" "LeakFault"];
member = read(ens);

mdl = "pumpModel";
leak = linspace(0, 1e-3, 20);
for k = numel(leak):-1:1
    simin(k) = Simulink.SimulationInput(mdl);
    simin(k) = setVariable(simin(k), "leakArea", leak(k));
end
[ok, E] = generateSimulationEnsemble(simin, "simResults", UseParallel=true);

reset(ens)
while hasdata(ens)
    m = read(ens);
    x = m.vibration{1}.Data;
    feat = table(rms(x), kurtosis(x), VariableNames=["RMS" "Kurtosis"]);
    writeToLastMemberRead(ens, feat);
end

